import java.util.Map;

public class ClassX {
    /**
     * Valida el encabezado del token para asegurar que el algoritmo es compatible.
     * 
     * La función verifica si el campo 'alg' en el encabezado contiene 'HS256'.
     *
     * @param header El mapa que representa el encabezado del token, donde las claves son cadenas (e.g., "alg")
     *               y los valores son cadenas (e.g., "HS256").
     * @throws IllegalArgumentException Si el encabezado es nulo, no contiene la clave 'alg', o si el valor
     *                                  de 'alg' no es "HS256".
     */
    public void validateTokenHeader(Map<String, String> header) {
        if (header == null) {
            throw new IllegalArgumentException("El encabezado del token no puede ser nulo.");
        }

        String algorithm = header.get("alg");

        if (algorithm == null || !algorithm.equals("HS256")) {
            throw new IllegalArgumentException("Algoritmo de token no soportado o ausente en el encabezado. Se esperaba 'HS256'.");
        }
    }
}
