public class ClassX {
    /**
     * Sanitizes user input by removing script tags.
     * 
     * The function uses string replacement to strip out <script> tags.
     * This method performs a case-insensitive replacement for both opening
     * and closing script tags.
     *
     * @param input The raw user input string.
     * @return The sanitized string with script tags removed.
     */
    public String sanitizeInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }
        // Remove <script> tags (case-insensitive)
        String sanitized = input.replaceAll("(?i)<script>", "");
        // Remove </script> tags (case-insensitive)
        sanitized = sanitized.replaceAll("(?i)</script>", "");
        return sanitized;
    }
}
