        for (String domain : blacklistDomains) {
            if (targetUrl != null && targetUrl.contains(domain)) {
                throw new IllegalArgumentException("Η στοχευμένη διεύθυνση URL περιέχει έναν τομέα που βρίσκεται στη μαύρη λίστα: " + domain);
